IComponent
Use this interface to implement a component and register it with the sdk.
``` function Box() { this.inputs = { visible: false, };
this.onInit = function() { var THREE = this.context.three; var geometry = new THREE.BoxGeometry(1, 1, 1); this.material = new THREE.MeshBasicMaterial(); var mesh = new THREE.Mesh( geometry, this.material ); this.outputs.objectRoot = mesh; };
this.onEvent = function(type, data) { }
this.onInputsUpdated = function(previous) { };
this.onTick = function(tickDelta) { }
this.onDestroy = function() { this.material.dispose(); }; }
function BoxFactory() { return new Box(); }
// Registering the component with the sdk sdk.Scene.register('box', BoxFactory);
```

Sample custom tour.
``` const connect = function(sdk) { const mpSdk = sdk;
mpSdk.Tour.Event.on(Tour.Event.STEPPED, function(tourIndex){ console.log('Tour index ' + tourIndex); }); mpSdk.Tour.Event.on(Tour.Event.STARTED, function(){ console.log('Tour started'); }); mpSdk.Tour.Event.on(Tour.Event.STOPPED, function(){ console.log('Tour stopped'); });
mpSdk.Tour.getData() .then(function(tour) { console.log('tour has ' + tour.length + ' stops'); return mpSdk.Tour.start(0); }) .then(function(){ // console 'Tour started' // console -> 'Tour index 0' return mpSdk.Tour.next(); }) .then(function(){ // console -> 'Tour index 1' return mpSdk.Tour.step(3); }) .then(function(){ // console -> 'Tour index 3' return mpSdk.Tour.prev(); }) .then(function(){ // console -> 'Tour index 2' // console -> 'Tour stopped' return mpSdk.Tour.stop(); }); } ```
